async function swap(ev, current) {
  let next;
  secDivs.forEach( (s, i) => {
    // console.log(s.classList);
    if( s.classList.contains("active") ) {
      next = i;
      // console.log("next is: ", s, i);
    }
  });
  // console.log("current and next: ", current, next);
  if( next !== current ) {
    swapSections(current, next);
  }
}

async function swapSections(current, next){
  let c = current;
  let n = next;

  // console.log("starting... ", c, n);
  let cClasses = [];
  let nClasses = [];

  secDivs[c].classList.forEach( (cls) => { if( cls !== "hide") cClasses.push(cls); });
  secDivs[n].classList.forEach( (cls) => { if( cls !== "active") nClasses.push(cls); });

  // console.log("cC", cClasses);
  // console.log("nC", nClasses,);
  
  secDivs[n].classList.add("slide-out-bck-center");

  setTimeout( () => {
    secDivs[n].classList.add("hide");
    secDivs[n].classList.remove("active");
  }, 500);

  setTimeout( () => {
    secDivs[c].classList.remove("hide");
    secDivs[c].classList.add("active", "slide-in-bck-center");

    
  }, 700);

  setTimeout( () => {
      secDivs[c].classList.remove("slide-out-bck-center");
      secDivs[c].classList.remove("slide-in-bck-center");
      secDivs[n].classList.remove("slide-out-bck-center");
    }, 1500 );
}

