function startAutoUpdater(){
  let payload = ["start", 2];
  if( typeof(Worker) !== "undefined"){
    if( updater == null ){
      updater = new Worker( new URL("./workers/auto-updater.js", import.meta.url));
    }
    updater.postMessage(...[payload]);

    updater.onmessage = function(e){
      // console.log("onMessage: ", e.data);
      getUpdate();
    };

  } else {
    alert("Web Workers not supported by your browser!");
  }

}

function stopAutoUpdater(){
  // console.log("turning off updates");
  let payload = ["stop", 0];
  // updater.postMessage(...[payload]);
  if( updater != null ){
    updater.postMessage(...[payload]);
    updater.terminate();
    updater = null;
    // console.log("updated was still running, terminating now.");
  } 
  // else {
  //  console.log("already terminated, but why?");
  // }
}

function getUpdate(){
  // console.log("getting update ...");
  let location = pref.getLocation();
  let timestamp = JSON.parse(localStorage.getItem('currentWeather')).time;
  let nextUpdate = DateTime.fromISO(timestamp).plus({minutes: 15}).toISO();
  let now = DateTime.local().toISO();

  // console.log("time for update?", nextUpdate <= now );

  if( nextUpdate <= now ) testLocation(location);
}


